import React from 'react';

export default function StatusBadge({ action, dept }) {
  if (!action) return <span className="badge b-none">No Status</span>;
  // Standard workflow statuses
  if (action === 'IN' || action === 'OUT' || action === 'DONE') {
    const cls = action === 'IN' ? 'b-in' : action === 'OUT' ? 'b-out' : 'b-done';
    const icon = action === 'IN' ? '↓' : action === 'OUT' ? '↑' : '✓';
    return (
      <span className={`badge ${cls}`}>
        {icon} {action}{dept ? ` @ ${dept}` : ''}
      </span>
    );
  }

  // Non-status actions (uploads/deletes/edits) - render a neutral badge with the action label
  return (
    <span className="badge b-none">
      {action}{dept ? ` @ ${dept}` : ''}
    </span>
  );
}
